def product_card(p, prefix=''):
    search=' '.join([p['title'],p['brand'],p['models'],p['engine'],p['codes'],*p.get('keywords',[])])
    img=prefix+'assets/'+p['image']
    return f'''<article class="product-card" data-product-card data-brand="{esc(p['brand'])}" data-search="{esc(search)}"><a class="product-image" href="{prefix}urun/{p['slug']}.html"><img src="{img}" data-fallback="{prefix}assets/motor-placeholder.svg" alt="{esc(p['title'])}" loading="lazy" onerror="this.onerror=null;this.src='{prefix}assets/motor-placeholder.svg'"></a><div class="product-content"><div class="p-labels"><span class="pill">{esc(p['brand'])}</span><span class="pill gray">{esc(p['family'])}</span></div><h3><a href="{prefix}urun/{p['slug']}.html">{esc(p['title'])}</a></h3><p>{esc(p['description'])}</p><div class="spec-row"><span>Motor kodu</span><strong>{esc(p['codes'])}</strong></div><div class="spec-row"><span>Model</span><strong>{esc(p['models'])}</strong></div><div class="spec-row"><span>Durum</span><strong>Talebe göre teyit edilir</strong></div><div class="product-actions"><a class="btn btn-primary btn-small" href="{prefix}urun/{p['slug']}.html">İncele</a><a class="btn btn-whatsapp btn-small" href="{wa_link(PHONE1,p['title']+' için bilgi almak istiyorum.')}" target="_blank" rel="noopener">WhatsApp: 0553 738 38 06</a><a class="btn btn-outline btn-small" href="tel:+905348441861">Ara: 0534 844 18 61</a></div></div></article>'''

def product_grid(products, prefix=''):
    return ''.join(product_card(p,prefix) for p in products)

